CREATE TABLE "IntegrationRoomHistory" ("roomId" VARCHAR(128) NOT NULL, "integrationId" VARCHAR(128) NOT NULL, "externalRoomHash" VARCHAR(128) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, "closedAt" TIMESTAMP(3), "closedReason" VARCHAR(64), "expiresAt" TIMESTAMP(3) NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IntegrationRoomHistory_pkey" PRIMARY KEY ("roomId"));
CREATE TABLE "IntegrationRoomParticipantSession" ("id" VARCHAR(128) NOT NULL, "roomId" VARCHAR(128) NOT NULL, "participantId" VARCHAR(128) NOT NULL, "displayName" VARCHAR(160) NOT NULL, "joinedAt" TIMESTAMP(3) NOT NULL, "leftAt" TIMESTAMP(3), CONSTRAINT "IntegrationRoomParticipantSession_pkey" PRIMARY KEY ("id"), CONSTRAINT "IntegrationRoomParticipantSession_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "IntegrationRoomHistory"("roomId") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "IntegrationRoomChatMessage" ("id" VARCHAR(128) NOT NULL, "roomId" VARCHAR(128) NOT NULL, "kind" VARCHAR(32) NOT NULL, "participantId" VARCHAR(128), "authorName" VARCHAR(160) NOT NULL, "text" VARCHAR(4000) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IntegrationRoomChatMessage_pkey" PRIMARY KEY ("id"), CONSTRAINT "IntegrationRoomChatMessage_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "IntegrationRoomHistory"("roomId") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "IntegrationRoomHistory_integrationId_roomId_idx" ON "IntegrationRoomHistory"("integrationId", "roomId");
CREATE INDEX "IntegrationRoomHistory_expiresAt_idx" ON "IntegrationRoomHistory"("expiresAt");
CREATE INDEX "IntegrationRoomParticipantSession_roomId_joinedAt_idx" ON "IntegrationRoomParticipantSession"("roomId", "joinedAt");
CREATE INDEX "IntegrationRoomParticipantSession_roomId_participantId_leftAt_idx" ON "IntegrationRoomParticipantSession"("roomId", "participantId", "leftAt");
CREATE INDEX "IntegrationRoomChatMessage_roomId_createdAt_id_idx" ON "IntegrationRoomChatMessage"("roomId", "createdAt", "id");